import {integrate,nmdaState,RELEASE_STEPS} from './synaptic-model.js';
const n=v=>String(v).replace('-', '−');
export function createSynapticState(){return {nE:20,nI:0,aE:1,aI:2,releaseStep:0,glutamate:true,coagonist:true,depolarized:false};}
export function renderIntegrationResult(state){
 const r=integrate(state),low=Math.min(-90,r.voltage-10),high=Math.max(-30,r.voltage+10),pos=v=>20+(v-low)/(high-low)*260;
 return `<div class="synaptic-equation">−70 + ${state.nE} × ${state.aE} − ${state.nI} × ${state.aI}<strong>= ${n(r.voltage)} mV</strong></div><svg class="integration-gauge" viewBox="0 0 300 93" role="img" aria-label="Potentiel calculé ${n(r.voltage)} mV ; repos moins 70 ; seuil moins 50"><path d="M20 36H280" stroke="#c6d9cc" stroke-width="8" stroke-linecap="round"/><line x1="${pos(-70)}" x2="${pos(-70)}" y1="22" y2="52" stroke="#779384" stroke-width="1.5"/><line x1="${pos(-50)}" x2="${pos(-50)}" y1="15" y2="58" stroke="#d6485a" stroke-width="2" stroke-dasharray="3 3"/><circle cx="${pos(r.voltage)}" cy="36" r="7" fill="${r.reached?'#d6485a':'#367c63'}" stroke="white" stroke-width="2"/><text x="${pos(-70)}" y="70" text-anchor="middle">−70</text><text x="${pos(-50)}" y="86" text-anchor="middle">seuil −50 mV</text></svg><strong class="integration-verdict">${r.reached?'Seuil atteint dans ce modèle':'Seuil non atteint'}</strong><p>${r.reached?'Ces entrées atteignent les conditions de seuil du modèle. La valeur calculée est une somme avant décharge, pas le pic du PA.':`Il manque ${n(r.missing)} mV nets pour atteindre le seuil.`}</p><dl class="integration-details"><div><dt>Excitation</dt><dd>+${r.excitation} mV</dd></div><div><dt>Inhibition</dt><dd>−${r.inhibition} mV</dd></div><div><dt>PPSE nécessaires avec cette inhibition</dt><dd>${r.minimum} au minimum</dd></div></dl>`;
}
export function renderNmdaResult(state){
 const r=nmdaState(state);
 const reason=!state.glutamate?'Le glutamate manque : la dépolarisation ne remplace pas le ligand.':!state.coagonist?'Le coagoniste manque : glutamate et dépolarisation ne suffisent pas.':r.blocked?'Les ligands sont présents, mais le potentiel négatif maintient un bloc Mg²⁺ important.':'Les ligands sont présents et la dépolarisation soulage le bloc Mg²⁺ : le courant devient possible dans ce modèle.';
 return `<svg class="nmda-lab-diagram" viewBox="0 0 300 185" role="img" aria-label="Récepteur NMDA : ${r.conducts?'courant possible':'courant empêché dans les conditions choisies'}"><rect x="5" y="10" width="290" height="57" rx="8" fill="#f0f5fa"/><rect x="5" y="122" width="290" height="58" rx="8" fill="#edf5ef"/><path d="M5 85H295M5 110H295" stroke="#d6c6a7" stroke-width="7"/><rect x="116" y="72" width="20" height="54" rx="5" fill="#367c63"/><rect x="165" y="72" width="20" height="54" rx="5" fill="#367c63"/>${state.glutamate?'<circle cx="113" cy="65" r="7" fill="#d6485a"/>':''}${state.coagonist?'<circle cx="186" cy="65" r="7" fill="#caab53"/>':''}${r.blocked?'<circle cx="150" cy="97" r="10" fill="#a678b5"/><text x="150" y="102" text-anchor="middle" fill="white">Mg</text>':'<circle cx="249" cy="48" r="10" fill="#a678b5"/><text x="249" y="52" text-anchor="middle" fill="white">Mg</text>'}${r.conducts?'<path d="M150 40V155l-5-7m5 7 5-7" stroke="#4b83b0" stroke-width="3" fill="none"/>':''}<text x="150" y="25" text-anchor="middle" fill="#4b83b0">Ca²⁺</text><text x="14" y="30">Extérieur</text><text x="14" y="162">Intérieur</text></svg><strong class="nmda-verdict">${r.conducts?'Courant NMDA possible':'Conditions insuffisantes'}</strong><p>${reason}</p><p class="lab-small-note">La levée du bloc est graduelle dans la réalité. Ces cases représentent des conditions qualitatives ; elles ne calculent ni le courant ni un voltage exact.</p>`;
}
export function renderSynapticLab(kind,state){
 if(kind==='release'){
  const i=state.releaseStep,s=RELEASE_STEPS[i];
  return `<div class="lab-heading"><p class="eyebrow">LA TRANSMISSION, PAS À PAS</p><h2>Du PA au message suivant</h2><p>Chaque étape garde son compartiment et son mécanisme.</p></div><div class="release-picture"><img src="./assets/diagrams/synapse-practice.svg" alt="Synapse chimique : bouton en haut, compartiment postsynaptique en bas"><span class="diagram-target" style="left:${s.x}%;top:${s.y}%" aria-hidden="true"></span></div><div class="release-steps">${RELEASE_STEPS.map((p,j)=>`<button data-synapse-step="${j}" aria-pressed="${i===j}" class="${i===j?'active':''}"><span>${j+1}</span>${p.label}</button>`).join('')}</div><div class="release-info" aria-live="polite"><p class="eyebrow">ÉTAPE ${i+1} / ${RELEASE_STEPS.length}</p><h3>${s.label}</h3><p>${s.explain}</p></div><p class="lab-small-note">Schéma pédagogique : aucune proportion moléculaire ou durée de transmission n’est mesurée ici.</p>`;
 }
 if(kind==='integration')return `<div class="lab-heading"><p class="eyebrow">LE MODÈLE D’EXERCICE DU COURS</p><h2>Le seuil est-il atteint ?</h2><p>Repos −70 mV, seuil −50 mV. Contributions simultanées, addition linéaire, sans réfractarité.</p></div><div class="integration-presets"><button data-integration-preset="20">20 PPSE</button><button data-integration-preset="26">26 PPSE + 3 PPSI</button><button data-integration-preset="19">Juste sous le seuil</button></div><label class="lab-label" for="integrationExcitation">Nombre de PPSE <output id="integrationExcitationValue">${state.nE}</output><input id="integrationExcitation" data-integration="nE" type="range" min="0" max="80" step="1" value="${state.nE}"></label><label class="lab-label">Amplitude d’un PPSE<select data-integration="aE" id="integrationExcitationSize">${[.5,1,1.5,2].map(v=>`<option value="${v}" ${state.aE===v?'selected':''}>+${v} mV</option>`).join('')}</select></label><label class="lab-label" for="integrationInhibition">Nombre de PPSI <output id="integrationInhibitionValue">${state.nI}</output><input id="integrationInhibition" data-integration="nI" type="range" min="0" max="10" step="1" value="${state.nI}"></label><label class="lab-label">Amplitude d’un PPSI<select data-integration="aI" id="integrationInhibitionSize">${[1,2,3].map(v=>`<option value="${v}" ${state.aI===v?'selected':''}>−${v} mV</option>`).join('')}</select></label><div id="integrationResult" class="synaptic-result" aria-live="polite">${renderIntegrationResult(state)}</div><p class="lab-small-note">Ce calcul n’est pas une simulation biophysique du neurone. Les PPS réels dépendent du temps, de leur localisation, des conductances et du voltage.</p>`;
 if(kind==='nmda')return `<div class="lab-heading"><p class="eyebrow">LES CONDITIONS D’ACTIVATION</p><h2>Pourquoi NMDA reste-t-il bloqué ?</h2><p>Change une condition à la fois pour distinguer ligand, coagoniste et voltage.</p></div><div class="nmda-conditions">${[['glutamate','Glutamate fixé'],['coagonist','Coagoniste présent'],['depolarized','Membrane suffisamment dépolarisée']].map(([id,label])=>`<label><input type="checkbox" data-nmda-condition="${id}" ${state[id]?'checked':''}><span>${label}</span></label>`).join('')}</div><div id="nmdaResult" class="synaptic-result" aria-live="polite">${renderNmdaResult(state)}</div>`;
 throw new Error('Atelier synaptique inconnu');
}
